-- App v0.65.1 e site 2.0.0: o GitHub é só por GitHub App, no login (o
-- provedor GitHub do Supabase Auth recebe as credenciais do GitHub App) e no
-- provedor git das organizações (sem o fluxo de OAuth App). A novidade da
-- versão e o uso da página orgRepositories da Documentação, nos dez idiomas.
on conflict (locale, key) do update set value = excluded.value;
